		/** 只处理我们自己的区域（面板与设置对话框），不碰宿主其它界面。 */
		function translateOurDom(): void {
			if (typeof document === 'undefined') return
			// 即时重新探测：DSH 的 locale 同步可能晚于本插件的 apply，缓存会被一次早到的 zh 覆盖。
			try { activeLocale = detectLocale() } catch (error) { /* 保持上一次的值 */ }
