/**
 * dsh-ui-auth — DSH Web UI 认证网关（正式部署版 Host 半区）。
 *
 * 在 DSH Web UI 的 node:http 服务器层拦截全部 HTTP 请求与 WebSocket 升级：
 * 未登录一律拒绝（页面请求重定向到登录页，API/静态资源返回 401，WS 升级销毁连接），
 * 覆盖 /api/*、/plugins/*、HMR、SPA fallback 等所有原接口，不留旁路。
 *
 * 用户数据持久化使用 credentials 服务（.credentials.yaml，每用户一条 grant 记录），
 * 密码以 PBKDF2-HMAC-SHA256（随机盐）存储，永不保存明文；令牌/盐优先使用
 * Web Crypto 强熵。首次启动自动创建管理员 admin（随机密码写入控制台日志与
 * dsh-ui-auth-bootstrap.txt）。
 */

import { createHash, randomUUID } from 'node:crypto'
import type { IncomingMessage, ServerResponse, Server } from 'node:http'
import type { Duplex } from 'node:stream'
import { createModernGateway } from './modern-gateway.js'
import type { ModernGateway, ModernGatewayContext } from './modern-gateway.js'
import type { Principal } from './modern-policy.js'
import {
  MAX_PASSKEYS,
  assessRelyingParty,
  authenticationOptions,
  createChallengeStore,
  factorState,
  finishAuthentication,
  finishRegistration,
  newUserHandle,
  normalizePasskeyLabel,
  reconcileTwoFactor,
  registrationOptions,
  relyingPartyIssueMessage,
  responseCredentialId,
  sanitizePasskeys,
  summarizePasskey,
} from './webauthn.js'
import type { PasskeyRelyingParty, RelyingPartyIssue, StoredPasskey } from './webauthn.js'
import { ProfileStore } from './model-profiles.js'
import { KekRegistry } from './profile-kek.js'
import { localeFromAcceptLanguage, translateHtml, translatePhrase, type Locale } from './i18n.js'
import { ProfileService } from './profile-service.js'
import { UserRouteRegistry, createDeepSeekRegistrar, routeIdOf } from './user-routes.js'

export const name = 'dsh-ui-auth'
export const inject = ['webServer', 'connection']

/**
 * Minimal Cordis context facade。`get()` 故意保持 `any`：这些名字背后是
 * 无类型的服务接缝对象，每个使用点都像手写 JS 那样自行校验形状。
 */
interface CordisContext extends ModernGatewayContext {
  get(name: string): any
  /**
   * Cordis 作用域注入：只在列出的服务可用时运行回调，并把一个**可以合法访问这些服务属性**的
   * 作用域上下文交给它。R1-ii 需要访问 `ctx.llm`（注册 provider 路由），但认证网关本身不应依赖 LLM，
   * 所以用作用域注入而不是把 `llm` 加进插件级 `inject`（那会让整个插件等待 LLM 服务）。
   */
  inject?(names: string[], callback: (scoped: CordisContext) => void): unknown
}

/** 用户记录（credentials 的 `dsh-auth/<key>` grant payload）。 */
interface UserRecord {
  v?: number
  username: string
  role: string
  salt: string
  hash: string
  iterations: number
  displayName?: string
  email?: string
  createdAt?: number
  updatedAt?: number
  totpSecret?: string
  totpEnabled?: boolean
  totpIgnore?: boolean
  twoFactor?: boolean
  /** 已绑定的通行密钥（仅存公钥与公开元数据，私钥永不离开用户设备）。 */
  passkeys?: StoredPasskey[]
  /** WebAuthn user handle（base64url，稳定不变，用于可发现凭据）。 */
  webauthnUserHandle?: string
}

/** 进程内会话条目（sha256(token) 十六进制 → 用户 + 过期时间）。 */
interface SessionEntry {
  username: string
  expiresAt: number
}

/** 单个客户端 IP 的失败计数（限流）。 */
interface FailEntry {
  count: number
  until: number
}

/** 一个邀请码（`dsh-auth/invites` payload 条目）。 */
interface InviteRecord {
  total: number
  used: number
  createdBy: string
  createdAt: number
}

/** `dsh-auth/ownership` payload（会话/工作区 id → 用户名）。 */
interface OwnershipTables {
  sessions: Map<string, string>
  workspaces: Map<string, string>
}

/**
 * 一次性身份验证票据（内存，单次使用，5 分钟有效）。
 * - purpose `login`：密码已通过，但该账号的第二步是通行密钥（2FA 开启且未绑定 TOTP）。
 * - purpose `stepup`：高强度校验已通过，可用于一次通行密钥管理操作（增删改）。
 * 票据绑定用户名与来源 IP，防止跨账号/跨来源重放。
 */
interface StepUpTicket {
  purpose: 'login' | 'stepup'
  username: string
  ip: string
  expiresAt: number
}

/** 插件运行时状态；`owners`/`invites` 在对象创建后立即挂载。 */
interface UiAuthState {
  users: Map<string, UserRecord>
  retiredUsers: Set<string>
  sessions: Map<string, SessionEntry>
  fails: Map<string, FailEntry>
  /** 一次性身份验证票据（密码通过后的第二步 / 通行密钥管理前的二次验证）。 */
  tickets: Map<string, StepUpTicket>
  ready: boolean
  fatal: string | null
  owners: OwnershipTables
  invites: Map<string, InviteRecord>
}

/** `dsh-ui-auth-sessions.json` 文件形状（v1）。 */
interface SessionsFile {
  v: number
  sessions: Record<string, SessionEntry>
}

/** `dsh-auth/ownership` 解码后的 payload。 */
interface OwnershipPayload {
  sessions?: Record<string, string> | null
  workspaces?: Record<string, string> | null
}

/** `dsh-auth/invites` 解码后的 payload。 */
interface InvitesPayload {
  codes?: Record<string, InviteEntry> | null
}

/** `dsh-auth/invites` payload 中的单个条目（字段仍需逐项校验）。 */
interface InviteEntry {
  total: number
  used: number
  createdBy?: string
  createdAt?: number
}

/** credentials 服务里的一条记录索引项。 */
interface CredentialEntry {
  key: string
}

/** credentials grant 记录：payload 为 JSON 字符串。 */
interface CredentialRecord {
  kind: string
  payload: string
}

/**
 * `ctx.get('credentials')` 接缝。`modifyRecord` 是全部持久化记录
 * （用户、归属表、邀请码）共用的 compare-and-set 写入器。
 */
interface CredentialsService {
  listRecords(): Promise<CredentialEntry[]>
  readRecord(key: string): Promise<CredentialRecord | undefined>
  modifyRecord(
    key: string,
    update: (current: CredentialRecord | undefined) => CredentialRecord | undefined | Promise<CredentialRecord | undefined>,
  ): Promise<CredentialRecord | undefined>
  deleteRecord(key: string): Promise<void>
}

/** 建立在 credentials 服务之上的持久化门面（缺失时退化为内存表）。 */
interface UiAuthStore {
  load(): Promise<void>
  create(record: UserRecord): Promise<boolean>
  mutate(
    username: string,
    fn: (record: UserRecord) => UserRecord | undefined | Promise<UserRecord | undefined>,
  ): Promise<UserRecord | undefined>
  remove(username: string): Promise<void>
  readRaw(key: string): Promise<string | undefined>
  writeRaw(key: string, payload: string): Promise<void>
}

/** `ctx.get('fs')` 接缝（路径相对进程工作目录）。 */
interface FsService {
  resolve(path: string): Promise<string>
  readText(path: string): Promise<string>
  writeText(path: string, text: string, options?: unknown): Promise<unknown>
  unlink?(path: string): Promise<unknown>
  processPath?(path: string): string
}

/** `ctx.get('webServer')` 接缝。 */
interface WebServerService {
  server?: Server
}

/** `clientIp` 看到的 req（保持结构化：调用方也会传裸对象）。 */
interface ClientIpRequest {
  socket?: { remoteAddress?: string } | undefined
  headers?: Record<string, any> | undefined
}

/** 环境变量解析出的限流/反代信任配置。 */
interface LockConfig {
  maxFails: number
  lockMs: number
  trustProxy: boolean
}

/** `performRegister` 的返回值：成功为 200，其余为错误状态 + 文案。 */
type RegisterResult =
  | { status: 200; ok: true; username: string }
  | { status: 400 | 403 | 409; error: string }

// ============ WebSocket 工具（RFC 6455 最小实现，零依赖） ============
// 仅保留 SHA-1 兜底：TOTP（RFC 6238）的 HMAC-SHA1 用它；WS 握手/帧编解码
// 曾用于 legacy 的 /api/events.mux 代理，已随 v0.7.0 移除 legacy 传输线一并删除
// （现代线由 `ws` 库处理 /api/remote.mux）。

/** 纯 JS SHA-1（crypto.createHash 不可用时的兜底）。 */
function sha1Fallback(data: string | Uint8Array): Uint8Array {
  // 参考实现：https://datatracker.ietf.org/doc/html/rfc3174 （算法公开）
  const bytes = typeof data === 'string' ? new TextEncoder().encode(data) : data
  const ml = bytes.length
  const padded = new Uint8Array((((ml + 8) >> 6) + 1) * 64)
  padded.set(bytes)
  padded[ml] = 0x80
  const dv = new DataView(padded.buffer)
  dv.setUint32(padded.length - 4, (ml * 8) >>> 0, false)
  let h0 = 0x67452301, h1 = 0xefcdab89, h2 = 0x98badcfe, h3 = 0x10325476, h4 = 0xc3d2e1f0
  const w = new Uint32Array(80)
  for (let i = 0; i < padded.length; i += 64) {
    for (let j = 0; j < 16; j++) w[j] = dv.getUint32(i + j * 4, false)
    for (let j = 16; j < 80; j++) {
      const n = w[j - 3] ^ w[j - 8] ^ w[j - 14] ^ w[j - 16]
      w[j] = ((n << 1) | (n >>> 31)) >>> 0
    }
    let a = h0, b = h1, c = h2, d = h3, e = h4
    for (let j = 0; j < 80; j++) {
      let f, k
      if (j < 20) { f = (b & c) | (~b & d); k = 0x5a827999 }
      else if (j < 40) { f = b ^ c ^ d; k = 0x6ed9eba1 }
      else if (j < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8f1bbcdc }
      else { f = b ^ c ^ d; k = 0xca62c1d6 }
      const temp = (((a << 5) | (a >>> 27)) + f + e + k + w[j]) >>> 0
      e = d; d = c; c = ((b << 30) | (b >>> 2)) >>> 0; b = a; a = temp
    }
    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0; h4 = (h4 + e) >>> 0
  }
  const out = new Uint8Array(20)
  const odv = new DataView(out.buffer)
  odv.setUint32(0, h0, false); odv.setUint32(4, h1, false); odv.setUint32(8, h2, false)
  odv.setUint32(12, h3, false); odv.setUint32(16, h4, false)
  return out
}

function wsSha1(data: string | Uint8Array): Uint8Array {
  try {
    return createHash('sha1').update(data).digest()
  } catch (err) {
    return sha1Fallback(data)
  }
}

/** 计算 Sec-WebSocket-Accept（base64(SHA1(key + GUID))）。 */

/** 编码一个服务端 → 客户端数据帧（FIN=1, opcode, 无掩码；支持 64 位扩展长度）。 */

/** 编码一个控制帧（close=8 / ping=9 / pong=10；可带 1-125 字节负载）。 */

// ============ TOTP（RFC 6238：HMAC-SHA1 + 30s 步进 + 6 位码） ============
// 纯 JS 实现（复用 WS 握手的 sha1Fallback），不引入外部依赖。
const B32_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567'

function base32Encode(bytes: Uint8Array): string {
  let bits = 0
  let value = 0
  let out = ''
  for (let i = 0; i < bytes.length; i++) {
    value = (value << 8) | bytes[i]
    bits += 8
    while (bits >= 5) {
      out += B32_ALPHABET[(value >>> (bits - 5)) & 31]
      bits -= 5
    }
  }
  if (bits > 0) out += B32_ALPHABET[(value << (5 - bits)) & 31]
  return out
}

function base32Decode(str: string): Uint8Array {
  const clean = String(str).toUpperCase().replace(/[^A-Z2-7]/g, '')
  let bits = 0
  let value = 0
  const out = []
  for (let i = 0; i < clean.length; i++) {
    const idx = B32_ALPHABET.indexOf(clean[i])
    if (idx === -1) continue
    value = (value << 5) | idx
    bits += 5
    if (bits >= 8) {
      out.push((value >>> (bits - 8)) & 0xff)
      bits -= 8
    }
  }
  return new Uint8Array(out)
}

function hmacSha1(keyBytes: Uint8Array, msgBytes: Uint8Array): Uint8Array {
  let key = keyBytes
  if (key.length > 64) key = sha1Fallback(key)
  const k = new Uint8Array(64)
  k.set(key)
  const ipad = new Uint8Array(64)
  const opad = new Uint8Array(64)
  for (let i = 0; i < 64; i++) { ipad[i] = k[i] ^ 0x36; opad[i] = k[i] ^ 0x5c }
  const inner = new Uint8Array(64 + msgBytes.length)
  inner.set(ipad, 0)
  inner.set(msgBytes, 64)
  const outer = new Uint8Array(64 + 20)
  outer.set(opad, 0)
  outer.set(sha1Fallback(inner), 64)
  return sha1Fallback(outer)
}

/** 指定时刻的 6 位 TOTP 码（RFC 6238，30s 步进）。 */
export function totpCodeAt(secretBase32: string, timeSec: number): string {
  let key
  try { key = base32Decode(secretBase32) } catch (err) { return '' }
  if (key.length === 0) return ''
  const counter = Math.floor(timeSec / 30)
  const msg = new Uint8Array(8)
  let c = counter
  for (let i = 7; i >= 0; i--) { msg[i] = c & 0xff; c = Math.floor(c / 256) }
  const h = hmacSha1(key, msg)
  const off = h[h.length - 1] & 0x0f
  const bin = ((h[off] & 0x7f) << 24) | (h[off + 1] << 16) | (h[off + 2] << 8) | h[off + 3]
  const code = (bin % 1000000).toString()
  return '000000'.slice(code.length) + code
}

/** 验证 6 位码（允许 ±1 时间窗口，即前后各 30 秒）。 */
export function totpVerifyCode(secretBase32: string, code: unknown): boolean {
  if (typeof code !== 'string' || !/^\d{6}$/.test(code)) return false
  const now = Date.now() / 1000
  for (let w = -1; w <= 1; w++) {
    if (totpCodeAt(secretBase32, now + w * 30) === code) return true
  }
  return false
}

/** 客户端 → 服务端帧流式解析器（浏览器下行通道只应出现 close/ping，仍完整支持掩码与分片）。 */

/** 从环境变量解析限流配置（DSH_AUTH_MAX_FAILS / DSH_AUTH_LOCK_MS / DSH_AUTH_TRUST_PROXY）。 */
export function readLockConfig(env?: Record<string, string | undefined> | null): LockConfig {
  const e = env !== undefined && env !== null ? env : {}
  const num = (v: unknown, d: number): number => { const n = Number(v); return Number.isInteger(n) && n > 0 ? n : d }
  return {
    maxFails: num(e.DSH_AUTH_MAX_FAILS, 5),
    lockMs: num(e.DSH_AUTH_LOCK_MS, 30 * 1000),
    trustProxy: ['1', 'true', 'yes', 'on'].includes(String(e.DSH_AUTH_TRUST_PROXY || '').trim().toLowerCase()),
  }
}

/**
 * 客户端来源 IP：默认取 socket.remoteAddress；仅当显式配置 DSH_AUTH_TRUST_PROXY=1
 * 时才信任 X-Forwarded-For（取最左，反代按 客户端→代理 顺序追加）。默认不信任，
 * 防止未配置反代时伪造 XFF 绕过/污染限流计数。
 */
export function clientIp(req: ClientIpRequest | undefined, trustProxy: boolean): string {
  try {
    const addr = req !== undefined && req.socket !== undefined ? req.socket.remoteAddress : undefined
    if (trustProxy && req !== undefined && req.headers !== undefined && typeof req.headers['x-forwarded-for'] === 'string') {
      // 取最右（最近受信反代追加的地址，客户端无法伪造）；从右向左跳过空段
      const parts = req.headers['x-forwarded-for'].split(',')
      for (let i = parts.length - 1; i >= 0; i--) {
        const p = parts[i].trim()
        if (p !== '') return p
      }
    }
    return typeof addr === 'string' ? addr : 'unknown'
  } catch (err) { return 'unknown' }
}

export function apply(ctx: CordisContext): void {
    // ============ 配置常量 ============
    // 会话密钥注册表：KEK 只属于本次挂载的会话，绝不跨挂载泄漏（每次 apply 都是新的）。
    const kekRegistry = new KekRegistry()
    // 会话 Cookie 名必须**按实例唯一**：浏览器的 Cookie 作用域不含端口，同一台机器上两个 DSH 实例
// （例如 127.0.0.1:3202 与 :3080）会共用同名 Cookie，后登录的实例会覆盖前一个，表现为"互相踢下线"。
// 以 DSH_HOME（每个实例一个）做短哈希后缀：实例内稳定（重启不掉线），实例之间互不干扰。
const COOKIE_NAME = 'dsh_auth_' + (() => {
  const seed = process.env.DSH_HOME ?? process.cwd()
  let hash = 0
  for (let i = 0; i < seed.length; i += 1) hash = (hash * 31 + seed.charCodeAt(i)) >>> 0
  return hash.toString(36)
})()
    const SCOPE = 'dsh-auth'
    const SESSION_TTL_MS = 12 * 60 * 60 * 1000 // 会话 12 小时，滑动续期
    const SESSION_SWEEP_MS = 5 * 60 * 1000
    const PBKDF2_ITERATIONS = 60000
    const MIN_PASSWORD = 8
    const MAX_PASSWORD = 128
    const MAX_BODY_BYTES = 64 * 1024
    // 限流配置：环境变量覆盖（DSH_AUTH_MAX_FAILS / DSH_AUTH_LOCK_MS / DSH_AUTH_TRUST_PROXY）
    const lock = readLockConfig(typeof process !== 'undefined' && process.env !== undefined ? process.env : {})
    const LOCKOUT_MAX_FAILS = lock.maxFails
    const LOCKOUT_MS = lock.lockMs
    const TRUST_PROXY = lock.trustProxy
    const USERNAME_RE = /^[A-Za-z0-9_.-]{2,32}$/
    // 通行密钥（WebAuthn）配置：默认按浏览器实际访问的主机推导 rpId/origin；
    // 反向代理或多域名部署可用环境变量显式指定（DSH_AUTH_RP_ID / DSH_AUTH_ORIGIN / DSH_AUTH_RP_NAME）。
    const PASSKEY_ENV = typeof process !== 'undefined' && process.env !== undefined ? process.env : {}
    const envText = (v: unknown): string | undefined => typeof v === 'string' && v.trim() !== '' ? v.trim() : undefined
    const RP_NAME = envText(PASSKEY_ENV.DSH_AUTH_RP_NAME)?.slice(0, 64) ?? 'DeepSeek Harness'
    const RP_ID_OVERRIDE = envText(PASSKEY_ENV.DSH_AUTH_RP_ID)
    const ORIGIN_OVERRIDE = envText(PASSKEY_ENV.DSH_AUTH_ORIGIN)
    const userRecordKey = (username: string): string => SCOPE + '/' + (/^[a-z][a-z0-9-]*$/.test(username) && !['ownership', 'invites', 'retired-users'].includes(username)
      ? username : 'user-' + createHash('sha256').update(username).digest('hex'))

    // ============ 纯 JS 密码学（沙箱无 crypto/Buffer） ============
    function rotr(x: number, n: number): number { return ((x >>> n) | (x << (32 - n))) >>> 0 }

    const K = new Uint32Array([
      0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
      0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
      0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
      0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
      0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
      0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
      0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
      0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    ])

    function sha256(data: Uint8Array): Uint8Array {
      const len = data.length
      const bitLenHi = Math.floor(len / 0x20000000)
      const bitLenLo = (len << 3) >>> 0
      const padded = new Uint8Array(((len + 8) >> 6 << 6) + 64)
      padded.set(data)
      padded[len] = 0x80
      const dv = new DataView(padded.buffer)
      dv.setUint32(padded.length - 8, bitLenHi)
      dv.setUint32(padded.length - 4, bitLenLo)
      const w = new Uint32Array(64)
      let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a
      let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19
      for (let i = 0; i < padded.length; i += 64) {
        for (let j = 0; j < 16; j++) w[j] = dv.getUint32(i + j * 4)
        for (let j = 16; j < 64; j++) {
          const s0 = rotr(w[j - 15], 7) ^ rotr(w[j - 15], 18) ^ (w[j - 15] >>> 3)
          const s1 = rotr(w[j - 2], 17) ^ rotr(w[j - 2], 19) ^ (w[j - 2] >>> 10)
          w[j] = (w[j - 16] + s0 + w[j - 7] + s1) >>> 0
        }
        let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7
        for (let j = 0; j < 64; j++) {
          const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)
          const ch = (e & f) ^ (~e & g)
          const t1 = (h + S1 + ch + K[j] + w[j]) >>> 0
          const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)
          const maj = (a & b) ^ (a & c) ^ (b & c)
          const t2 = (S0 + maj) >>> 0
          h = g; g = f; f = e; e = (d + t1) >>> 0
          d = c; c = b; b = a; a = (t1 + t2) >>> 0
        }
        h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0
        h4 = (h4 + e) >>> 0; h5 = (h5 + f) >>> 0; h6 = (h6 + g) >>> 0; h7 = (h7 + h) >>> 0
      }
      const out = new Uint8Array(32)
      const odv = new DataView(out.buffer)
      odv.setUint32(0, h0); odv.setUint32(4, h1); odv.setUint32(8, h2); odv.setUint32(12, h3)
      odv.setUint32(16, h4); odv.setUint32(20, h5); odv.setUint32(24, h6); odv.setUint32(28, h7)
      return out
    }

    function hmacSha256(key: Uint8Array, msg: Uint8Array): Uint8Array {
      const blockSize = 64
      let k = key
      if (k.length > blockSize) k = sha256(k)
      const iKey = new Uint8Array(blockSize)
      const oKey = new Uint8Array(blockSize)
      for (let i = 0; i < blockSize; i++) {
        const kb = i < k.length ? k[i] : 0
        iKey[i] = kb ^ 0x36
        oKey[i] = kb ^ 0x5c
      }
      const inner = new Uint8Array(blockSize + msg.length)
      inner.set(iKey)
      inner.set(msg, blockSize)
      const innerHash = sha256(inner)
      const outer = new Uint8Array(blockSize + innerHash.length)
      outer.set(oKey)
      outer.set(innerHash, blockSize)
      return sha256(outer)
    }

    function pbkdf2(password: Uint8Array, salt: Uint8Array, iterations: number): Uint8Array {
      const block = new Uint8Array(salt.length + 4)
      block.set(salt)
      block[salt.length + 3] = 1
      let u = hmacSha256(password, block)
      const result = new Uint8Array(u)
      for (let i = 1; i < iterations; i++) {
        u = hmacSha256(password, u)
        for (let j = 0; j < result.length; j++) result[j] ^= u[j]
      }
      return result
    }

    function toHex(bytes: Uint8Array): string {
      let s = ''
      for (let i = 0; i < bytes.length; i++) {
        const b = bytes[i]
        s += (b < 16 ? '0' : '') + b.toString(16)
      }
      return s
    }

    function hexToBytes(hex: string): Uint8Array {
      const out = new Uint8Array(Math.floor(String(hex).length / 2))
      for (let i = 0; i < out.length; i++) {
        const byte = parseInt(String(hex).slice(i * 2, i * 2 + 2), 16)
        out[i] = Number.isNaN(byte) ? 0 : byte
      }
      return out
    }

    function utf8(str: string): Uint8Array {
      return new TextEncoder().encode(str)
    }

    function randomBytes(n: number): Uint8Array {
      // 正式部署环境有 Web Crypto，用它提供强熵；沙箱里回退到 Math.random。
      if (typeof crypto !== 'undefined' && crypto !== null && typeof crypto.getRandomValues === 'function') {
        const out = new Uint8Array(n)
        crypto.getRandomValues(out)
        return out
      }
      const out = new Uint8Array(n)
      for (let i = 0; i < n; i++) out[i] = Math.floor(Math.random() * 256)
      return out
    }

    function randomHex(nBytes: number): string {
      return toHex(randomBytes(nBytes))
    }

    function randomPassword(len: number): string {
      const alphabet = 'abcdefghijkmnopqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ23456789!@#$%^&*'
      const bytes = randomBytes(len)
      let out = ''
      for (let i = 0; i < len; i++) out += alphabet[bytes[i] % alphabet.length]
      return out
    }

    function constantTimeEqual(a: unknown, b: unknown): boolean {
      if (typeof a !== 'string' || typeof b !== 'string' || a.length !== b.length) return false
      let diff = 0
      for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i)
      return diff === 0
    }

    function hashPassword(password: string, saltHex: string, iterations: number): string {
      return toHex(pbkdf2(utf8(password), hexToBytes(saltHex), iterations))
    }

    function newPasswordRecord(password: string): { salt: string; hash: string; iterations: number } {
      const salt = randomHex(16)
      return { salt, hash: hashPassword(password, salt, PBKDF2_ITERATIONS), iterations: PBKDF2_ITERATIONS }
    }

    function verifyPassword(record: UserRecord | undefined, password: string): boolean {
      if (record === undefined || typeof record.hash !== 'string' || typeof record.salt !== 'string') return false
      const iters = typeof record.iterations === 'number' && record.iterations > 0 ? record.iterations : PBKDF2_ITERATIONS
      return constantTimeEqual(hashPassword(password, record.salt, iters), record.hash)
    }

    // ============ 运行时状态 ============
    const state = {
      users: new Map(),   // username -> 用户记录（含 salt/hash，仅进程内）
      retiredUsers: new Set(),
      sessions: new Map(), // token -> { username, expiresAt }
      fails: new Map(),    // ip -> { count, until }
      tickets: new Map(),  // 一次性身份验证票据 -> { purpose, username, ip, expiresAt }
      ready: false,
      fatal: null,
    } as UiAuthState

    /** 通行密钥一次性挑战（注册/登录/管理前二次验证）。 */
    const passkeyChallenges = createChallengeStore()

    let creds: CredentialsService | undefined = ctx.get('credentials')
    let store: UiAuthStore | null = null

    // WP4：模型配置服务。**必须是持久实例**——它内部记录 uid→会话 token 的绑定，
    // 每次 RPC 新建实例会把绑定丢掉，解锁后立刻又变成 locked。store 就绪后（或换了实例）重建一次。
    /**
     * 服务端代查 DeepSeek 兼容接口的余额：只回数字，Key 永不外传。
     * baseURL 由配置提供（第 1 项要求创建分享时填写），缺省用官方地址。
     */
    const deepseekBalanceFetcher = async (apiKey: string, baseUrl?: string): Promise<{ currency: string; total: number; granted?: number; toppedUp?: number } | null> => {
      const origin = (baseUrl === undefined || baseUrl.trim() === '' ? 'https://api.deepseek.com' : baseUrl.trim()).replace(/\/+$/, '')
      try {
        const response = await fetch(origin + '/user/balance', {
          headers: { authorization: 'Bearer ' + apiKey, accept: 'application/json' },
        })
        if (!response.ok) return null
        const payload = await response.json() as { balance_infos?: Array<{ currency?: string; total_balance?: string; granted_balance?: string; topped_up_balance?: string }> }
        const info = payload.balance_infos?.[0]
        if (info === undefined) return null
        const num = (value: unknown): number | undefined => {
          const parsed = Number(value)
          return Number.isFinite(parsed) ? parsed : undefined
        }
        return {
          currency: typeof info.currency === 'string' ? info.currency : 'CNY',
          total: num(info.total_balance) ?? 0,
          ...(num(info.granted_balance) === undefined ? {} : { granted: num(info.granted_balance) as number }),
          ...(num(info.topped_up_balance) === undefined ? {} : { toppedUp: num(info.topped_up_balance) as number }),
        }
      } catch (error) {
        return null
      }
    }

    let profileServiceCache: ProfileService | null = null
    let profileServiceStore: UiAuthStore | null = null
    function profileService(): ProfileService | undefined {
      if (store === null) return undefined
      if (profileServiceCache === null || profileServiceStore !== store) {
        const profileStore = new ProfileStore(store)
        profileServiceCache = new ProfileService({
          store: profileStore,
          seam: store,
          registry: kekRegistry,
          sessionOwner: (sessionId: string) => ownerOfSession(sessionId),
          uidOf: async (username: string) => await profileStore.ensureUid(username),
          balanceFetcher: deepseekBalanceFetcher,
          // "当前密码"校验：按 uid 找到用户名，再读同一条 dsh-auth/<name> 记录做哈希比对
          readUserByUid: async (uid: string) => {
            for (const [username, record] of state.users.entries()) {
              const candidate = await profileStore.uidOf(username)
              if (candidate === uid) return { salt: record.salt, hash: record.hash, iterations: record.iterations }
            }
            return undefined
          },
          verifyPasswordAgainst: (user, password) => verifyPassword({ ...user, username: '', role: 'user' } as UserRecord, password),
        })
        profileServiceStore = store
      }
      return profileServiceCache
    }

    // ============ R1-ii：按用户配置的 provider 路由 ============
    // 每条"自有配置"与"对外分享的配置"对应宿主里的一条 provider 路由；路由的 resolveAuth 在调用瞬间
    // 从我们自己的加密存储解密 Key（私有→会话 KEK；分享→服务端主密钥）。宿主缺包时明确报错并停用该路径，
    // 不影响其余功能（Q2 阻断仍然生效）。
    let routeRegistry: UserRouteRegistry | null = null
    /** profileId → 归属 uid，用于同步时释放已失效的路由。 */
    const routeOwner = new Map<string, string>()

    async function syncRoutesFor(uid: string): Promise<void> {
      const registry = routeRegistry
      const service = profileService()
      if (registry === null || service === undefined) return
      const desired = new Set<string>()
      try {
        for (const meta of await service.listProfiles(uid)) {
          if (meta.source !== 'own') continue
          desired.add(meta.profileId)
          registry.ensure({
            profileId: meta.profileId,
            routeId: routeIdOf(meta.profileId),
            label: meta.label,
            model: meta.model,
            ...(meta.baseUrl === undefined ? {} : { baseUrl: meta.baseUrl }),
            resolveKey: () => service.resolveOwnPrivateKey(uid, meta.profileId),
          })
          routeOwner.set(meta.profileId, uid)
        }
        for (const shared of await service.listGrantedProfiles(uid)) {
          desired.add(shared.profileId)
          registry.ensure({
            profileId: shared.profileId,
            routeId: routeIdOf(shared.profileId),
            label: shared.label,
            model: shared.model,
            // 分享配置由服务端主密钥托管：所有者离线时被授权者仍可调用。
            resolveKey: () => service.resolveSharedKeyUnattended(uid, shared.profileId),
          })
          routeOwner.set(shared.profileId, uid)
        }
        // 释放该用户名下已不存在的配置（删除配置、取消分享）
        for (const [profileId, owner] of [...routeOwner.entries()]) {
          if (owner !== uid || desired.has(profileId)) continue
          registry.dispose(profileId)
          routeOwner.delete(profileId)
        }
      } catch (err) {
        console.error('[dsh-ui-auth] 同步用户 provider 路由失败: ' + String(err))
      }
    }

    async function syncAllRoutes(): Promise<void> {
      const service = profileService()
      if (service === undefined) return
      for (const username of state.users.keys()) {
        const uid = await service.uidOfName(username)
        if (uid !== undefined) await syncRoutesFor(uid)
      }
    }

    const startUserRoutes = async (scoped: CordisContext): Promise<void> => {
      const register = await createDeepSeekRegistrar(scoped)
      if (register === undefined) {
        console.error('[dsh-ui-auth] 宿主未提供 dsh-llm-deepseek / dsh-launch-environment：'
          + '按用户模型的调用路径（R1-ii）不可用；界面与存储隔离仍然生效，未配置的用户继续被阻断。')
        return
      }
      routeRegistry = new UserRouteRegistry({
        register,
        onError: (message, error) => console.error(`[dsh-ui-auth] ${message}: ${String(error)}`),
      })
      ctx.effect(() => () => {
        routeRegistry?.disposeAll()
        routeRegistry = null
        routeOwner.clear()
      }, 'dsh-ui-auth: 释放用户 provider 路由')
      await syncAllRoutes()
    }
    // 作用域注入 `llm`：Cordis 要求声明注入后才能访问 `ctx.llm`（registerDeepSeekProvider 内部会用到），
    // 而认证网关本身不依赖 LLM——因此只让这部分等待该服务，不把 `llm` 加进插件级 inject。
    if (typeof ctx.inject === 'function') {
      ctx.inject(['llm'], (scoped) => { void startUserRoutes(scoped) })
    } else {
      // 测试 harness / 老宿主没有作用域注入：直接尝试（缺服务时 createDeepSeekRegistrar 会返回 undefined）。
      void startUserRoutes(ctx)
    }

    /**
     * 用户记录边界规范化：任何读入或写出的记录都经过这里。
     * - passkeys 只保留结构合法的条目（防手工编辑、旧版本残留、超量注入）；
     * - 强制反锁死不变式：2FA 只有在账号仍保有可用因子时才保持开启。
     */
    function normalizeUserRecord(raw: UserRecord): UserRecord {
      const passkeys = sanitizePasskeys(raw.passkeys)
      const handle = raw.webauthnUserHandle
      const webauthnUserHandle = typeof handle === 'string' && handle.length > 0 && handle.length <= 128 ? handle : undefined
      const twoFactor = reconcileTwoFactor({ ...raw, passkeys })
      return {
        ...raw,
        passkeys,
        twoFactor,
        ...(webauthnUserHandle !== undefined ? { webauthnUserHandle } : { webauthnUserHandle: undefined }),
      }
    }

    // 用注入的服务构建持久化 store；payload 存 JSON 字符串（沙箱 realm 对象
    // 无法通过 credentials-local 的 host-realm Object.prototype 校验）。
    function buildStore(c: CredentialsService): UiAuthStore {
      return {
        async load() {
          const prefix = SCOPE + '/'
          const entries = await c.listRecords()
          for (const entry of entries) {
            if (typeof entry.key !== 'string' || !entry.key.startsWith(prefix)) continue
            const rec = await c.readRecord(entry.key)
            if (rec === undefined || rec.kind !== 'grant' || typeof rec.payload !== 'string') continue
            let p
            try { p = JSON.parse(rec.payload) } catch (err) { continue }
            if (p !== null && typeof p === 'object' && typeof p.v === 'number'
              && typeof p.hash === 'string' && typeof p.salt === 'string') {
              const username = typeof p.username === 'string' ? p.username : entry.key.slice(prefix.length)
              state.users.set(username, normalizeUserRecord(p as UserRecord))
            }
          }
        },
        async create(rec) {
          if (state.retiredUsers.has(rec.username)) return false
          const key = userRecordKey(rec.username)
          const normalized = normalizeUserRecord(rec)
          const jsonString = JSON.stringify(normalized)
          const written = await c.modifyRecord(key, async (current) => {
            if (current !== undefined) return undefined
            return { kind: 'grant', payload: jsonString }
          })
          if (written === undefined || written.kind !== 'grant' || written.payload !== jsonString) return false
          state.users.set(rec.username, normalized)
          return true
        },
        async mutate(username, fn) {
          const key = userRecordKey(username)
          const written = await c.modifyRecord(key, async (current) => {
            if (current === undefined || current.kind !== 'grant' || typeof current.payload !== 'string') return undefined
            let parsed
            try { parsed = JSON.parse(current.payload) } catch (err) { return undefined }
            if (parsed === null || typeof parsed !== 'object') return undefined
            const next = await fn(normalizeUserRecord(parsed as UserRecord))
            if (next === undefined) return undefined
            return { kind: 'grant', payload: JSON.stringify(normalizeUserRecord(next)) }
          })
          if (written !== undefined && written.kind === 'grant' && typeof written.payload === 'string') {
            let parsed
            try { parsed = JSON.parse(written.payload) } catch (err) { return undefined }
            const normalized = normalizeUserRecord(parsed as UserRecord)
            state.users.set(username, normalized)
            return normalized
          }
          return undefined
        },
        async remove(username) {
          await c.modifyRecord(SCOPE + '/retired-users', async current => {
            const retired = current?.kind === 'grant' && typeof current.payload === 'string' ? JSON.parse(current.payload) : []
            return { kind: 'grant', payload: JSON.stringify([...new Set([...retired, username])]) }
          })
          state.retiredUsers.add(username)
          state.users.delete(username)
          await c.deleteRecord(userRecordKey(username))
        },
        async readRaw(key) {
          const rec = await c.readRecord(key)
          if (rec === undefined || rec.kind !== 'grant' || typeof rec.payload !== 'string') return undefined
          return rec.payload
        },
        async writeRaw(key, payload) {
          await c.modifyRecord(key, async (current) => {
            if (current !== undefined && current.kind === 'grant') {
              return { kind: 'grant', payload: current.payload === payload ? current.payload : payload }
            }
            return { kind: 'grant', payload }
          })
        },
      }
    }

    // credentials 服务可能在插件 apply 之后才挂载（启动顺序竞态）：
    // 有界等待它就绪，避免误走内存兜底导致每次重启生成新管理员。
    async function acquireCredentials(timeoutMs: number): Promise<void> {
      if (creds !== undefined) return
      const deadline = Date.now() + timeoutMs
      while (creds === undefined && Date.now() < deadline) {
        creds = ctx.get('credentials')
        if (creds !== undefined) break
        await new Promise(resolve => setTimeout(resolve, 200))
      }
      if (creds !== undefined && store === null) store = buildStore(creds)
    }

    if (creds !== undefined) store = buildStore(creds)

    async function storeMutate(username: string, fn: (record: UserRecord) => UserRecord | undefined | Promise<UserRecord | undefined>): Promise<UserRecord | undefined> {
      if (store !== null) return store.mutate(username, fn)
      const cur = state.users.get(username)
      if (cur === undefined) return undefined
      const next = await fn(cur)
      if (next === undefined) return undefined
      state.users.set(username, next)
      return next
    }

    async function storeCreate(rec: UserRecord): Promise<boolean> {
      if (state.retiredUsers.has(rec.username)) return false
      if (store !== null) return store.create(rec)
      if (state.users.has(rec.username)) return false
      state.users.set(rec.username, rec)
      return true
    }

    async function storeRemove(username: string): Promise<void> {
      if (store !== null) return store.remove(username)
      state.users.delete(username)
    }

    // ============ 会话 ============
    // 会话持久化（0.4.0）：会话表落盘到 dsh-ui-auth-sessions.json（fs 服务工作目录），
    // 重启后恢复未过期会话 —— token 明文落盘等价于"记住登录态"，文件仅属主可读写。
    const SESSIONS_FILE = 'dsh-ui-auth-sessions.json'
    let sessionsDirty = false

    function persistSessions() {
      if (!sessionsDirty) return
      try {
        const fsSvc: FsService | undefined = ctx.get('fs')
        if (fsSvc === undefined) return
        const data: SessionsFile = { v: 1, sessions: {} }
        for (const [token, s] of state.sessions) data.sessions[token] = { username: s.username, expiresAt: s.expiresAt }
        sessionsDirty = false
        fsSvc.resolve(SESSIONS_FILE).then((t) => fsSvc.writeText(t, JSON.stringify(data))).catch((err) => console.error('[dsh-ui-auth] 写入会话文件失败: ' + String(err)))
      } catch (err) { /* ignore */ }
    }

    async function loadSessions() {
      try {
        const fsSvc: FsService | undefined = ctx.get('fs')
        if (fsSvc === undefined) return
        const t = await fsSvc.resolve(SESSIONS_FILE)
        const text = await fsSvc.readText(t)
        const data: SessionsFile = JSON.parse(text)
        if (data === null || typeof data !== 'object' || data.v !== 1 || typeof data.sessions !== 'object' || data.sessions === null) return
        const now = Date.now()
        let loaded = 0
        for (const [key, s] of Object.entries(data.sessions)) {
          // v0.5.1：只接受哈希格式 key（64 位 hex）；旧版明文 token 记录升级后不再恢复
          if (typeof key !== 'string' || !/^[0-9a-f]{64}$/.test(key)) continue
          if (typeof s !== 'object' || s === null || typeof s.username !== 'string' || typeof s.expiresAt !== 'number') continue
          if (s.expiresAt <= now) continue // 已过期不恢复
          if (!state.users.has(s.username)) continue // 用户已不存在则不恢复
          state.sessions.set(key, { username: s.username, expiresAt: Math.min(s.expiresAt, now + SESSION_TTL_MS) })
          loaded++
        }
        if (loaded > 0) console.log('[dsh-ui-auth] 已恢复 ' + loaded + ' 个持久化会话（重启不掉线）')
      } catch (err) { /* 文件不存在/损坏：从空会话开始 */ }
    }

    /** 会话 token 哈希（内存 key 与落盘均用哈希，磁盘不存明文 token）。 */
    function hashToken(token: string): string {
      return toHex(sha256(new TextEncoder().encode(String(token))))
    }

    function createSession(username: string): string {
      let token = randomHex(24)
      while (state.sessions.has(hashToken(token))) token = randomHex(24)
      state.sessions.set(hashToken(token), { username, expiresAt: Date.now() + SESSION_TTL_MS })
      sessionsDirty = true
      persistSessions()
      return token
    }

    function resolveSession(token: string | undefined, touch = true): string | undefined {
      if (token === undefined) return undefined
      const key = hashToken(token)
      const s = state.sessions.get(key)
      if (s === undefined) return undefined
      const now = Date.now()
      if (s.expiresAt <= now) {
        state.sessions.delete(key)
        sessionsDirty = true
        return undefined
      }
      if (touch) s.expiresAt = now + SESSION_TTL_MS
      return s.username
    }

    function destroySession(token: string | undefined): void {
      if (token !== undefined && state.sessions.delete(hashToken(token))) {
        sessionsDirty = true
        persistSessions()
      }
    }

    function invalidateSessions(username: string, exceptToken?: string): void {
      let changed = false
      for (const [token, s] of state.sessions) {
        if (s.username === username && token !== exceptToken) { state.sessions.delete(token); changed = true }
      }
      if (changed) {
        sessionsDirty = true
        persistSessions()
      }
    }

    function adminCount(): number {
      let n = 0
      for (const u of state.users.values()) if (u.role === 'admin') n++
      return n
    }

    // ============ 数据归属（按登录用户隔离会话/工作区） ============
    // DSH 是单用户应用，会话/工作区为机器级数据；认证层需要按登录用户隔离。
    // 归属表持久化在 credentials 记录 dsh-auth/ownership（payload=JSON 字符串），
    // 内存缓存供读路径使用。未打标的数据默认归 admin（旧数据对普通用户不可见）。
    // 隔离范围：列表/搜索/工作区响应过滤 + 直连访问按归属拦截 + 创建打标；
    // 事件流（events.mux/host WebSocket）无法在网关层逐帧过滤，属已知边界。
    const OWNERSHIP_KEY = SCOPE + '/ownership'
    state.owners = { sessions: new Map(), workspaces: new Map() }

    async function loadOwnership(): Promise<void> {
      if (store === null) return
      const rec = await store.readRaw(OWNERSHIP_KEY)
      if (rec === undefined) return
      let p: OwnershipPayload | null
      try { p = JSON.parse(rec) } catch (err) { return }
      if (p !== null && typeof p === 'object' && p.sessions !== null && typeof p.sessions === 'object'
        && p.workspaces !== null && typeof p.workspaces === 'object') {
        state.owners.sessions = new Map(Object.entries(p.sessions))
        state.owners.workspaces = new Map(Object.entries(p.workspaces))
      }
    }

    async function persistOwnership(): Promise<void> {
      if (store === null) return
      const payload = JSON.stringify({
        v: 1,
        sessions: Object.fromEntries(state.owners.sessions),
        workspaces: Object.fromEntries(state.owners.workspaces),
      })
      await store.writeRaw(OWNERSHIP_KEY, payload)
    }

    let ownershipWrites = Promise.resolve()
    function claimOwner(kind: 'sessions' | 'workspaces', id: string, username: string): Promise<void> {
      const write = ownershipWrites.then(async () => {
        if (typeof id !== 'string' || id.length === 0 || id.length > 256 || !state.users.has(username)) throw new Error('Invalid ownership attribution')
        const table = state.owners[kind]
        const previous = table.get(id)
        if (previous !== undefined && previous !== username) throw new Error('Object already belongs to another user')
        table.set(id, username)
        try { await persistOwnership() }
        catch (error) { if (previous === undefined) table.delete(id); throw error }
      })
      ownershipWrites = write.catch(() => {})
      return write
    }
    const setSessionOwner = (id: string, username: string): Promise<void> => claimOwner('sessions', id, username)
    const setWorkspaceOwner = (id: string, username: string): Promise<void> => claimOwner('workspaces', id, username)

    function ownerOfSession(sessionId: string): string {
      return state.owners.sessions.get(sessionId) ?? 'admin'
    }

    function ownerOfWorkspace(workspaceId: string): string {
      return state.owners.workspaces.get(workspaceId) ?? 'admin'
    }

    // ============ 邀请码（注册功能，0.5.0） ============
    // 持久化在 credentials 记录 dsh-auth/invites（payload=JSON 字符串）。
    // 每个码：total（可注册次数）/ used（已用次数）/ createdBy / createdAt。
    const INVITES_KEY = SCOPE + '/invites'
    const INVITE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789' // 去除易混淆字符
    state.invites = new Map()

    function inviteCode(): string {
      let out = ''
      for (let i = 0; i < 8; i++) out += INVITE_ALPHABET[randomBytes(1)[0] % INVITE_ALPHABET.length]
      return out
    }

    /** 生成随机 TOTP 密钥（20 字节 → base32；使用本 apply 的强熵随机源）。 */
    function totpGenerateSecret(): string {
      return base32Encode(randomBytes(20))
    }

    async function loadInvites(): Promise<void> {
      if (store === null) return
      const rec = await store.readRaw(INVITES_KEY)
      if (rec === undefined) return
      let p: InvitesPayload | null
      try { p = JSON.parse(rec) } catch (err) { return }
      if (p !== null && typeof p === 'object' && p.codes !== null && typeof p.codes === 'object') {
        for (const [code, v] of Object.entries(p.codes)) {
          if (v !== null && typeof v === 'object' && typeof v.total === 'number' && typeof v.used === 'number') {
            state.invites.set(code, {
              total: v.total,
              used: v.used,
              createdBy: typeof v.createdBy === 'string' ? v.createdBy : 'admin',
              createdAt: typeof v.createdAt === 'number' ? v.createdAt : 0,
            })
          }
        }
      }
    }

    async function persistInvites(): Promise<void> {
      if (store === null) return
      const payload = JSON.stringify({ v: 1, codes: Object.fromEntries(state.invites) })
      await store.writeRaw(INVITES_KEY, payload)
    }

    // ============ HTTP 工具 ============
    function pathnameOf(rawUrl: unknown): string {
      if (typeof rawUrl !== 'string') return '/'
      const q = rawUrl.indexOf('?')
      const p = q === -1 ? rawUrl : rawUrl.slice(0, q)
      try { return decodeURIComponent(p) } catch (err) { return p }
    }

    function readCookie(req: IncomingMessage, name: string): string | undefined {
      const header = req.headers !== undefined ? req.headers.cookie : undefined
      if (typeof header !== 'string') return undefined
      const prefix = name + '='
      for (const part of header.split(';')) {
        const t = part.trim()
        if (t.startsWith(prefix)) return t.slice(prefix.length)
      }
      return undefined
    }

    function readBody(req: IncomingMessage, limit: number): Promise<string> {
      return new Promise((resolve, reject) => {
        let size = 0
        let text = ''
        const dec = new TextDecoder()
        req.on('data', (chunk) => {
          size += chunk.length
          if (size > limit) {
            reject(new Error('body too large'))
            try { req.destroy() } catch (e) { /* ignore */ }
            return
          }
          text += dec.decode(chunk, { stream: true })
        })
        req.on('end', () => { text += dec.decode(); resolve(text) })
        req.on('error', reject)
      })
    }

    function clientIpOf(req: ClientIpRequest | undefined): string {
      return clientIp(req, TRUST_PROXY)
    }

    /**
     * 服务端侧语言：宿主把"没有显式偏好"的情况交给浏览器，我们照同一规则办——
     * 因此这里优先看请求的 `Accept-Language`（登录/注册页通常发生在 SPA 之前，请求头是唯一可靠信号），
     * 读不到就回落到中文。客户端界面则由 DSH 的 locale 服务驱动（见 client.ts）。
     */
    function requestLocale(req?: IncomingMessage): Locale {
      try {
        const header = req?.headers['accept-language']
        const value = Array.isArray(header) ? header[0] : header
        return localeFromAcceptLanguage(value) ?? 'zh'
      } catch (error) {
        return 'zh'
      }
    }

    /** 错误消息按同一词典翻译（`sendJson` 是唯一出口，故只在这里做一次）。 */
    function localizedError(res: ServerResponse, obj: unknown): unknown {
      const locale = (res as ServerResponse & { dshuaLocale?: Locale }).dshuaLocale
      if (locale !== 'en' || typeof obj !== 'object' || obj === null) return obj
      const record = obj as Record<string, unknown>
      if (typeof record.error !== 'string') return obj
      return { ...record, error: translatePhrase('en', record.error) }
    }

    function sendJson(res: ServerResponse, status: number, obj: unknown): void {
      if (res.headersSent) { try { res.destroy() } catch (e) { /* ignore */ } return }
      try {
        res.writeHead(status, {
          'content-type': 'application/json; charset=utf-8',
          'cache-control': 'no-store',
        })
        res.end(JSON.stringify(localizedError(res, obj)))
      } catch (err) {
        try { res.destroy() } catch (e) { /* ignore */ }
      }
    }

    function redirect(res: ServerResponse, location: string): void {
      if (res.headersSent) { try { res.destroy() } catch (e) { /* ignore */ } return }
      try {
        res.writeHead(302, { location, 'cache-control': 'no-store' })
        res.end()
      } catch (err) {
        try { res.destroy() } catch (e) { /* ignore */ }
      }
    }

    /** 请求是否处于安全通道：TLS 直连，或（仅当信任反代时）X-Forwarded-Proto: https。 */
    function isSecureRequest(req: IncomingMessage): boolean {
      try {
        if (req.socket !== undefined && (req.socket as unknown as { encrypted?: boolean }).encrypted === true) return true
        if (TRUST_PROXY && req.headers !== undefined && req.headers['x-forwarded-proto'] === 'https') return true
      } catch (err) { /* ignore */ }
      return false
    }

    function setAuthCookie(res: ServerResponse, token: string, secure: boolean): void {
      try {
        res.setHeader('set-cookie', COOKIE_NAME + '=' + token + '; Path=/; HttpOnly; SameSite=Strict' + (secure ? '; Secure' : '') + '; Max-Age=' + Math.floor(SESSION_TTL_MS / 1000))
      } catch (err) { /* ignore */ }
    }

    function clearAuthCookie(res: ServerResponse, secure: boolean): void {
      try {
        res.setHeader('set-cookie', COOKIE_NAME + '=; Path=/; HttpOnly; SameSite=Strict' + (secure ? '; Secure' : '') + '; Max-Age=0')
      } catch (err) { /* ignore */ }
    }

    function publicUser(p: UserRecord): Principal & { displayName: string; email: string; createdAt: number; totpEnabled: boolean; totpIgnore: boolean; twoFactor: boolean; passkeyCount: number } {
      return {
        username: p.username,
        role: p.role === 'admin' ? 'admin' : 'user',
        displayName: typeof p.displayName === 'string' ? p.displayName : '',
        email: typeof p.email === 'string' ? p.email : '',
        createdAt: typeof p.createdAt === 'number' ? p.createdAt : 0,
        totpEnabled: p.totpEnabled === true,
        totpIgnore: p.totpIgnore === true,
        twoFactor: p.twoFactor === true,
        passkeyCount: factorState(p).passkeyCount,
      }
    }

    function passwordError(pw: unknown): string | null {
      if (typeof pw !== 'string') return '密码格式错误'
      if (pw.length < MIN_PASSWORD) return '密码至少 ' + MIN_PASSWORD + ' 位'
      if (pw.length > MAX_PASSWORD) return '密码过长（最多 ' + MAX_PASSWORD + ' 位）'
      // 复杂度：至少两种字符类型（大写/小写字母、数字、符号）
      const kinds = [/[a-z]/, /[A-Z]/, /[0-9]/, /[^a-zA-Z0-9]/].filter((re) => re.test(pw)).length
      if (kinds < 2) return '密码需包含至少两种字符类型（大写字母、小写字母、数字、符号）'
      return null
    }

    function recordFail(ip: string): void {
      const cur = state.fails.get(ip)
      const count = (cur === undefined ? 0 : cur.count) + 1
      state.fails.set(ip, count >= LOCKOUT_MAX_FAILS
        ? { count, until: Date.now() + LOCKOUT_MS }
        : { count, until: 0 })
    }

    // ============ 一次性身份验证票据（0.6.4） ============
    // 用于两类场景：密码已通过但第二步是通行密钥；以及通行密钥管理操作前的高强度校验。
    // 票据只在内存中、单次使用、5 分钟过期，并绑定用户名与来源 IP。
    const TICKET_TTL_MS = 5 * 60 * 1000
    const TICKET_MAX = 256

    function issueTicket(purpose: StepUpTicket['purpose'], username: string, ip: string): string {
      const now = Date.now()
      for (const [handle, ticket] of state.tickets) {
        if (ticket.expiresAt <= now) state.tickets.delete(handle)
      }
      while (state.tickets.size >= TICKET_MAX) {
        const oldest = state.tickets.keys().next().value
        if (oldest === undefined) break
        state.tickets.delete(oldest)
      }
      const handle = randomHex(24)
      state.tickets.set(handle, { purpose, username, ip, expiresAt: now + TICKET_TTL_MS })
      return handle
    }

    type TicketCheck = { ok: true } | { ok: false; error: string }

    /**
     * 校验票据。`consume` 为 true 时立即删除（单次使用）；为 false 时只校验，
     * 供「先取参数、后提交」的两步流程在第一步校验、第二步消费。
     */
    function checkTicket(handle: unknown, purpose: StepUpTicket['purpose'], username: string, ip: string, consume: boolean): TicketCheck {
      if (typeof handle !== 'string' || handle.length === 0 || handle.length > 128) {
        return { ok: false, error: '本次验证已失效，请重新验证身份' }
      }
      const ticket = state.tickets.get(handle)
      if (ticket === undefined) return { ok: false, error: '本次验证已失效，请重新验证身份' }
      if (consume) state.tickets.delete(handle)
      if (ticket.expiresAt <= Date.now()) return { ok: false, error: '验证已超时，请重新验证身份' }
      if (ticket.purpose !== purpose) return { ok: false, error: '本次验证已失效，请重新验证身份' }
      if (ticket.username !== username) return { ok: false, error: '本次验证不属于当前账号，请重新验证身份' }
      if (ticket.ip !== ip) return { ok: false, error: '来源地址已变化，请重新验证身份' }
      return { ok: true }
    }

    const consumeTicket = (handle: unknown, purpose: StepUpTicket['purpose'], username: string, ip: string): TicketCheck =>
      checkTicket(handle, purpose, username, ip, true)

    const peekTicket = (handle: unknown, purpose: StepUpTicket['purpose'], username: string, ip: string): TicketCheck =>
      checkTicket(handle, purpose, username, ip, false)

    /** 登录页内联脚本用的 HTML 转义（页面里注入的值只来自服务端常量，仍按不可信处理）。 */
    function escapeHtml(value: string): string {
      return value
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;').replace(/'/g, '&#39;')
    }

    /** 内联 JSON 的 `<` 转义，避免字符串中出现 `</script>` 提前结束脚本块。 */
    function jsonForScript(value: unknown): string {
      return JSON.stringify(value).replace(/</g, '\\u003c')
    }

    /**
     * 登录页需要知道的通行密钥可用性（不含任何秘密）。
     * 地址不可用时给出原因与建议地址，页面据此显示提示而不是坏按钮。
     */
    function loginPasskeyUi(req: IncomingMessage): { supported: boolean; error?: string; suggestedHost?: string; rpId?: string } {
      const context = passkeyContext(req)
      if ('rp' in context) return { supported: true, rpId: context.rp.rpId }
      const ui: { supported: boolean; error?: string; suggestedHost?: string } = { supported: false, error: context.error }
      if (context.suggestedHost !== undefined) ui.suggestedHost = context.suggestedHost
      return ui
    }

