  check('WS-ISO', '代理上游连接带 nonce 头（防自我递归）', gateway.includes('MUX_PROXY_HEADER'))
  check('WS-ISO', '被隐藏的 waterfall 接收方仍会释放投递（否则属主的 next 挂住）',
