    index.includes('modern.handleUpgrade(') && index.includes('DSH_AUTH_MUX_PROXY'))
  check('WS-ISO', '自研 mux 死代码已移除（不再经 typertGateway.wireStream 自建流）',
    !gateway.includes('wireStream') && !gateway.includes('MAX_STREAMS'))
