    if (trigger) trigger.click()
  })
  await wait(1500)
  await dismissOverlays()
  await clickNav('用户管理')
  await wait(1800)
  await dismissOverlays()

  const root = await page.$('.dshua')
  if (root === null) throw new Error('未找到「用户管理」页容器（.dshua）')
  // 打印各表格的表头与行数，便于确认成图内容（脚本不读图）
